import { lock, unlock, clearBodyLocks } from "tua-body-scroll-lock";

export interface IModal extends HTMLElement {
  showModal(): void;
  hideModal(): void;
}

export class Modal extends HTMLElement implements IModal {
  public modal: HTMLElement | null;
  private closeModalButtons: HTMLElement[];
  private focusableElements: NodeListOf<HTMLElement> | null;
  private firstFocusableElement: HTMLElement | null;
  private lastFocusableElement: HTMLElement | null;
  private lastFocusedElement: HTMLElement | null = null;
  private modalName: string | null;

  constructor() {
    super();
    this.modal = null;
    this.closeModalButtons = [];
    this.focusableElements = null;
    this.firstFocusableElement = null;
    this.lastFocusableElement = null;
    this.modalName = null;
  }

  connectedCallback(): void {
    this.getModalName();
    this.cacheDomElements();
    this.setupEventListeners();
  }

  disconnectedCallback(): void {
    clearBodyLocks();
  }

  private getModalName(): void {
    this.modalName = this.getAttribute("modal-name");
    if (!this.modalName) {
      throw new Error("Modal name attribute is required");
    }
  }

  private cacheDomElements(): void {
    this.modal = this;

    if (!this.modal) {
      throw new Error("Modal element not found");
    }
    this.closeModalButtons = Array.from(
      this.querySelectorAll("[data-close-modal]"),
    );
  }

  private setupEventListeners(): void {
    this.closeModalButtons.forEach((button) => {
      button.addEventListener("click", () => this.hideModal());
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        this.hideModal();
      }
    });

    const overlay = this.querySelector(".modal__overlay");
    if (overlay) {
      overlay.addEventListener("click", this.overlayClickHandler.bind(this));
    }

    document.addEventListener(`modal:show:${this.modalName}`, () =>
      this.showModal(),
    );

    document.addEventListener(`modal:hide:${this.modalName}`, () =>
      this.hideModal(),
    );
  }

  private overlayClickHandler(): void {
    if (!this.hasAttribute("persist-dialog")) {
      this.hideModal();
    }
  }

  public showModal(): void {
    this.lastFocusedElement = document.activeElement as HTMLElement;
    this.modal!.setAttribute("aria-hidden", "false");
    this.classList.add("is-open");

    this.setupFocusTrap();
    lock(this.modal);
  }

  public hideModal(): void {
    this.modal!.setAttribute("aria-hidden", "true");
    this.classList.remove("is-open");

    document.removeEventListener("keydown", this.trapFocus);

    // Restore focus to the element that was focused before the modal was opened
    if (
      this.lastFocusedElement &&
      typeof this.lastFocusedElement.focus === "function"
    ) {
      this.lastFocusedElement.focus();
    }
    unlock(this.modal);
    document.dispatchEvent(new CustomEvent(`modal:closed:${this.modalName}`));
  }

  private setupFocusTrap(): void {
    this.focusableElements = this.modal!.querySelectorAll(
      'a[href], area[href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), button:not([disabled]), iframe, object, embed, [tabindex]:not([tabindex="-1"]), [contenteditable]',
    );
    if (this.focusableElements.length) {
      this.firstFocusableElement = this.focusableElements[0];
      this.lastFocusableElement =
        this.focusableElements[this.focusableElements.length - 1];
      this.firstFocusableElement.focus();

      document.addEventListener("keydown", this.trapFocus.bind(this));
    }
  }

  private trapFocus(event: KeyboardEvent): void {
    if (event.key === "Tab") {
      if (event.shiftKey) {
        if (document.activeElement === this.firstFocusableElement) {
          this.lastFocusableElement?.focus();
          event.preventDefault();
        }
      } else if (document.activeElement === this.lastFocusableElement) {
        this.firstFocusableElement?.focus();
        event.preventDefault();
      }
    }
  }
}
