import { h } from "preact";
import type { JSX } from "preact";
import { useEffect, useRef, useState } from "preact/hooks";
import { createPortal } from "preact/compat";
import { CartData, Cart } from "../../cart";
import MiniCartHeader from "./MiniCartHeader";
import { refreshMiniCart } from "@theme/minicart-sync";
import { disablePageScroll, enablePageScroll } from "@fluejs/noscroll";

interface MiniCartProps {
  open: "true" | "false";
}

function MiniCart({ open }: MiniCartProps) {
  const [isOpen, setIsOpen] = useState<boolean>(open === "true");
  const [cartData, setCartData] = useState<CartData | null>(null);
  const cartRef = useRef<Cart>(document.querySelector("uwp-cart"));

  // Keep internal state in sync with attribute changes
  useEffect(() => {
    setIsOpen(open === "true");
  }, [open]);

  useEffect(() => {
    const cartElement = cartRef.current;
    if (!cartElement) return;

    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (
          mutation.type === "attributes" &&
          mutation.attributeName === "cart-data"
        ) {
          const updatedData = JSON.parse(
            cartElement.getAttribute("cart-data") || "{}",
          );
          setCartData(updatedData);
        }
      });
    });

    observer.observe(cartElement, { attributes: true });

    return () => observer.disconnect();
  }, []);

  // When opened, refresh contents from server-rendered cart HTML
  useEffect(() => {
    if (isOpen) refreshMiniCart();
  }, [isOpen]);

  // Lock body scroll when minicart is open
  useEffect(() => {
    if (isOpen) {
      disablePageScroll();
    } else {
      enablePageScroll();
    }

    return () => {
      enablePageScroll();
    };
  }, [isOpen]);

  const toggleDrawer = () => {
    setIsOpen(!isOpen);
  };

  const drawerClass = `minicart__drawer${isOpen ? " is-open" : ""}`;

  const handleBackdropClick = (e: JSX.TargetedMouseEvent<HTMLDivElement>) => {
    if (e.currentTarget === e.target) toggleDrawer();
  };

  const handleBackdropKeyDown = (
    e: JSX.TargetedKeyboardEvent<HTMLDivElement>,
  ) => {
    if (e.key === "Escape" || e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      toggleDrawer();
    }
  };

  return (
    <div>
      <button
        onClick={toggleDrawer}
        className="minicart__toggle"
        aria-label={window.themeVars.strings.accessibility.cartOpen}
      >
        <div
          dangerouslySetInnerHTML={{ __html: window.themeVars.icons.cart }}
        ></div>
        <span className="minicart__count eyebrow-2xs">
          <span className="minicart__count-inner">
            {cartData?.item_count || 0}
          </span>
        </span>
      </button>
      {createPortal(
        <div
          className={drawerClass}
          role="button"
          aria-label={window.themeVars.strings.accessibility.cartClose}
          tabIndex={0}
          onClick={handleBackdropClick}
          onKeyDown={handleBackdropKeyDown}
        >
          <div className="minicart__main" role="dialog" aria-modal="true">
            <MiniCartHeader
              toggleDrawer={toggleDrawer}
              itemCount={cartData?.item_count || 0}
            />
            <div className="minicart__body-wrapper">
              <div className="minicart__body" />
              <div className="minicart__upsells" />
            </div>
            <div className="minicart__footer" />
          </div>
        </div>,
        document.body,
      )}
    </div>
  );
}

export default MiniCart;
